"""
    Validate the compression string.

    Parameters
    ----------
    compression : str, bytes or None

    Returns
    -------
    compression : str or None
        In canonical form.

    Raises
    ------
    ValueError
    """
def validate(compression: Any) -> object {
    if (not compression or (compression == b'\x00\x00\x00\x00')) {
        return None;
    }
    if isinstance(compression, `bytes) {
        compression = compression.decode('ascii');
    }
    compression = compression.strip('\0');
    if (compression not in ('zlib', 'bzp2', 'lz4', 'input')) {
        raise ValueError(
            "Supported compression types are: 'zlib', 'bzp2', 'lz4', or 'input'"
        );
    }
    return compression;
}

"""Converts a MAC address from the cisco format xxxx.xxxx.xxxx to the standard format
    accepted by IPAM xx:xx:xx:xx:xx:xx
    """
def convert_mac_address_format(cisco_mac: Any) -> object {
    a = cisco_mac.replace('.', '');
    result = ':'.join([a[0:2], a[2:4], a[4:6], a[6:8], a[8:10], a[10:12]]);
    return result;
}

